import { Component, computed, inject, input, model, output, signal } from '@angular/core';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import {
  TablerIconComponent, IconChevronRight, IconChevronDown, IconBell, IconBuilding,
  IconSettings, IconLayoutSidebarLeftCollapse, IconLayoutSidebarLeftExpand,
} from '@tabler/icons-angular';
import { HrmSideNav, HrmNavItem, HrmNavSection, HrmSideNavUser } from 'hrm-ui';
import { buildNavSections } from './_template-nav';

/** sg-template-side-nav — CHROME SIDE NAV CHUẨN của mọi trang template (nguồn duy nhất).
 *  Gói trọn hrm-side-nav + logo + nút thu gọn + chuông + khối tài khoản doanh nghiệp +
 *  khối user (gear "Thiết lập") + nav sections mặc định (buildNavSections, song ngữ).
 *  → Sửa chrome/nav Ở ĐÂY (hoặc trong hrm-side-nav gốc) = 14 template đổi đồng loạt.
 *  Trang chỉ truyền `selectedKey`; trường hợp đặc biệt override `sections` (setup-guide:
 *  nav kiêm anchor wizard) hoặc bắt `(itemClick)`.
 *  <sg-template-side-nav appSideNav selectedKey="dashboard" /> */
@Component({
  selector: 'sg-template-side-nav',
  imports: [HrmSideNav, TablerIconComponent, TranslateModule],
  template: `
    <hrm-side-nav [sections]="sections() ?? defaultSections()" [selectedKey]="selectedKey()"
      [caretIcon]="caret" [logoSrc]="logo" [logoMarkSrc]="logoMark"
      [toggleIcon]="sbCollapse" [expandIcon]="sbExpand" [(collapsed)]="collapsedModel"
      [user]="user()" [switchIcon]="gear" [switchLabel]="'docs.appShell.navSettings' | translate"
      (itemClick)="itemClick.emit($event)">
      <button snActions type="button" class="as-ico" [attr.aria-label]="'docs.appShell.ariaNotify' | translate"><tabler-icon [icon]="bell" [size]="20" /></button>
      <button snHead type="button" class="sn-acct" [class.sn-acct--mini]="collapsed()">
        <span class="sn-acct-ic"><tabler-icon [icon]="building" [size]="18" /></span>
        @if (!collapsed()) {
          <span class="sn-acct-info">
            <span class="sn-acct-name">Tập đoàn VNR</span>
            <span class="sn-acct-sub">{{ 'docs.appShell.acctEnterprise' | translate }}</span>
          </span>
          <tabler-icon [icon]="chevDown" [size]="16" style="color:var(--text-soft)" />
        }
      </button>
    </hrm-side-nav>
  `,
  /* display:contents → hrm-side-nav là con trực tiếp của .shell-side (flex full cao như cũ). */
  styles: [`
    :host { display: contents; }
    .as-ico { display: grid; place-items: center; width: 34px; height: 34px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .sn-acct { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); cursor: pointer; text-align: left; }
    .sn-acct--mini { width: auto; padding: 4px; border-color: transparent; background: transparent; }
    .sn-acct-ic { display: grid; place-items: center; width: 32px; height: 32px; border-radius: var(--radius-md); background: var(--primary-bg-subtle); color: var(--primary-base); flex: none; }
    .sn-acct-info { flex: 1; min-width: 0; display: flex; flex-direction: column; }
    .sn-acct-name { font-size: var(--fs-13); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .sn-acct-sub { font-size: var(--fs-12); color: var(--text-soft); }
  `],
})
export class SgTemplateSideNav {
  /** Key mục nav đang chọn — khác biệt DUY NHẤT giữa các template thông thường. */
  readonly selectedKey = input('');
  /** Override cấu trúc nav (hiếm — VD setup-guide nav kiêm anchor). Bỏ trống = nav mặc định. */
  readonly sections = input<HrmNavSection[] | null>(null);
  /** User demo chuẩn; override khi cần. */
  readonly user = input<HrmSideNavUser>({ name: 'Đặng Anh', email: 'danganh@vnr.vn' });
  /** Two-way — trang cần biết trạng thái thu gọn thì [(collapsed)]. */
  readonly collapsed = model(false);
  readonly itemClick = output<HrmNavItem>();

  private readonly t = inject(TranslateService);
  private readonly lang = signal(this.t.currentLang);
  constructor() { this.t.onLangChange.subscribe((e) => this.lang.set(e.lang)); }
  /** Nav mặc định — recompute khi đổi ngôn ngữ (idiom lang() của styleguide). */
  protected readonly defaultSections = computed<HrmNavSection[]>(() => (this.lang(), buildNavSections(this.t)));

  /** Two-way [(collapsed)] cần get/set (bind bare signal không tự .set — idiom codebase). */
  protected get collapsedModel(): boolean { return this.collapsed(); }
  protected set collapsedModel(v: boolean) { this.collapsed.set(v); }

  protected readonly logo = '/assets/vnr-logo-full.svg';
  protected readonly logoMark = '/assets/vnr-logo-mark.svg';
  protected readonly caret = IconChevronRight;
  protected readonly chevDown = IconChevronDown;
  protected readonly bell = IconBell;
  protected readonly building = IconBuilding;
  protected readonly gear = IconSettings;
  protected readonly sbCollapse = IconLayoutSidebarLeftCollapse;
  protected readonly sbExpand = IconLayoutSidebarLeftExpand;
}
