import {
  IconLayoutDashboard, IconUsers, IconSitemap, IconFileText, IconClock,
  IconClipboardList, IconUserPlus, IconBriefcase, IconClipboardCheck, IconWallet,
  IconCalendarEvent, IconDatabase,
} from '@tabler/icons-angular';
import { TranslateService } from '@ngx-translate/core';
import { HrmNavSection } from 'hrm-ui';

/** Side-nav MẶC ĐỊNH dùng chung cho mọi template mẫu — cùng 1 cấu trúc module (đồng bộ chrome).
 *  NGUỒN DUY NHẤT: mọi template lấy nav qua `sg-template-side-nav` (đến lượt nó gọi factory này) —
 *  sửa cấu trúc ở đây → tất cả template đổi theo. Nhãn qua i18n docs.appShell.* (song ngữ).
 *  Mỗi trang chỉ đổi `selectedKey`. */
export function buildNavSections(t: TranslateService): HrmNavSection[] {
  const l = (k: string) => t.instant('docs.appShell.' + k);
  return [
    { header: l('navMain'), items: [
      { key: 'dashboard', label: l('navDashboard'), icon: IconLayoutDashboard },
      { key: 'employee', label: l('navHr'), icon: IconUsers, children: [
        { key: 'emp-list', label: l('navEmpList'), icon: IconUsers },
        { key: 'org', label: l('navOrg'), icon: IconSitemap },
        { key: 'contract', label: l('navContract'), icon: IconFileText },
      ] },
      { key: 'attendance', label: l('navAttendance'), icon: IconClock, children: [
        { key: 'timesheet', label: l('navTimesheet'), icon: IconClock },
        { key: 'shift', label: l('navShift'), icon: IconCalendarEvent },
      ] },
      { key: 'requests', label: l('navRequests'), icon: IconClipboardList },
      { key: 'recruit', label: l('navRecruit'), icon: IconUserPlus, children: [
        { key: 'jobs', label: l('navJobs'), icon: IconBriefcase },
        { key: 'candidates', label: l('navCandidates'), icon: IconUsers },
      ] },
      { key: 'evaluation', label: l('navEvaluation'), icon: IconClipboardCheck },
      { key: 'payroll', label: l('navPayroll'), icon: IconWallet },
      { key: 'catalog', label: l('navCatalog'), icon: IconDatabase },
    ] },
  ];
}
